package gg.savira.client;

import net.minecraft.client.gui.DrawContext;

/**
 * Savira's 10x10 pixel icons: drawn in one colour (white by default, accent on hover), in the
 * spirit of the launcher's line icons, instead of Minecraft items.
 */
public final class PixelIcons {
    private PixelIcons() {}

    public static final String[] PLAYER = { "...####...", "..######..", "..######..", "..######..", "...####...", "..........", ".########.", "##########", "##########", "##########" };
    public static final String[] GLOBE = { "...####...", ".##.##.##.", ".#..##..#.", "##########", "#...##...#", "#...##...#", "##########", ".#..##..#.", ".##.##.##.", "...####..." };
    public static final String[] GEAR = { "....##....", ".#.####.#.", "..######..", ".###..###.", "####..####", "####..####", ".###..###.", "..######..", ".#.####.#.", "....##...." };
    public static final String[] LANGUAGE = { "#########.", "#.......#.", "#..###..#.", "#.#...#.#.", "#.#####.#.", "#.#...#.#.", "#.......#.", "#########.", "..##......", ".#........" };
    public static final String[] EYE = { "..........", "..######..", ".#......#.", "#...##...#", "#..####..#", "#..####..#", "#...##...#", ".#......#.", "..######..", ".........." };
    public static final String[] IMAGE = { "##########", "#........#", "#.##.....#", "#.##.....#", "#......#.#", "#.....####", "#..#.#####", "#.########", "##########", ".........." };
    public static final String[] HUD = { "####.#####", "####.#####", "####......", "..........", "#####.####", "#####.####", "#####.####", "..........", "##########", "##########" };
    public static final String[] SHIRT = { "##.####.##", "###....###", "##########", ".########.", "..######..", "..######..", "..######..", "..######..", "..######..", ".........." };
    public static final String[] EMOTE = { "..######..", ".#......#.", "#..#..#..#", "#..#..#..#", "#........#", "#.#....#.#", "#..####..#", ".#......#.", "..######..", ".........." };
    public static final String[] FRIENDS = { ".##....##.", "####..####", "####..####", ".##....##.", "..........", "####..####", "##########", "##########", "##########", ".........." };
    public static final String[] SEARCH = { "..####....", ".#....#...", "#......#..", "#......#..", "#......#..", ".#....#...", "..####.#..", ".......##.", "........##", ".........#" };
    public static final String[] BACK = { "..........", "...#......", "..##......", ".#########", "##########", ".#########", "..##......", "...#......", "..........", ".........." };
    public static final String[] HEADPHONES = { "..######..", ".#......#.", "#........#", "#........#", "#........#", "###....###", "###....###", "###....###", "###....###", ".........." };
    public static final String[] RESET = { "...#####..", "..#.....#.", ".#.......#", "#.........", "#.........", "#......#..", ".#....###.", "..#..#####", "...##.....", ".........." };

    // Light/dark switch of the menu header (9x9, drawn at 1 unit per pixel).
    public static final String[] SUN = { "#...#...#", ".#.....#.", "...###...", "..#####..", "#.#####.#", "..#####..", "...###...", ".#.....#.", "#...#...#" };
    public static final String[] MOON = { "...####..", ".####....", ".###.....", "###......", "###......", "###......", ".###....#", ".#######.", "...####.." };

    // One icon per HUD module.
    public static final String[] FPS = { "........##", "........##", "....##..##", "....##..##", "##..##..##", "##..##..##", "##..##..##", "##..##..##", "..........", "##########" };
    public static final String[] CPS = { "...####...", "..#.##.#..", ".#..##..#.", ".#..##..#.", ".########.", ".#......#.", ".#......#.", ".#......#.", "..#....#..", "...####..." };
    public static final String[] KEYS = { "...####...", "...#..#...", "...####...", "..........", "####.####.", "#..#.#..#.", "####.####.", "..........", ".########.", ".########." };
    public static final String[] PING = { "..######..", ".#......#.", "#..####..#", "..#....#..", ".#..##..#.", "...#..#...", "..........", "....##....", "....##....", ".........." };
    public static final String[] PIN = { "...####...", "..#....#..", ".#..##..#.", ".#.#..#.#.", ".#..##..#.", "..#....#..", "..#....#..", "...#..#...", "....##....", ".........." };
    public static final String[] ARMOR = { "##......##", "###....###", "##########", ".########.", ".###..###.", ".########.", ".########.", ".########.", ".########.", ".........." };
    public static final String[] POTION = { "...####...", "....##....", "....##....", "...#..#...", "..#....#..", ".#......#.", ".########.", ".########.", "..######..", ".........." };
    public static final String[] SPRINT = { "#....#....", "##...##...", ".##...##..", "..##...##.", "...##...##", "..##...##.", ".##...##..", "##...##...", "#....#....", ".........." };
    public static final String[] ZOOM = { "..####....", ".#....#...", "#..##..#..", "#.####.#..", "#..##..#..", ".#....#...", "..####.#..", ".......##.", "........##", ".........#" };
    public static final String[] RAM = { ".#.#.#.#..", "##########", "#........#", "#.######.#", "#.######.#", "#........#", "##########", ".#.#.#.#..", "..........", ".........." };

    public static String[] module(HudModule module) {
        return switch (module) {
            case FPS -> FPS; case CPS -> CPS; case KEYSTROKES -> KEYS; case PING -> PING; case COORDINATES -> PIN;
            case ARMOR -> ARMOR; case POTIONS -> POTION; case SPRINT -> SPRINT; case ZOOM -> ZOOM; case RAM -> RAM; case ICON -> FRIENDS; case NAMETAG -> PLAYER; case LIGHT_LEVEL -> PIN;
        };
    }

    /** Draws a 10x10 icon at (x, y); px is the size of one icon pixel. */
    public static void draw(DrawContext c, String[] rows, int x, int y, int px, int color) {
        for (int row = 0; row < rows.length; row++) {
            String line = rows[row];
            for (int col = 0; col < line.length(); col++) if (line.charAt(col) == '#') c.fill(x + col * px, y + row * px, x + (col + 1) * px, y + (row + 1) * px, color);
        }
    }
}
